import pixeltable as pxt
from pixeltable.type_system import StringType, IntType, FloatType

pxt.create_dir('demo', if_exists='ignore')
tbl = pxt.create_table(
    'demo.films',
    schema={
        'title': StringType(),
        'year': IntType(),
        'revenue': FloatType()
    },
    if_exists='replace'
)
tbl.insert([
    {'title': 'Jaws', 'year': 1975, 'revenue': 470.7},
    {'title': 'Alien', 'year': 1979, 'revenue': 184.7}
])
